({ tick, justPressed, state }) => {
  const commands = [];
  if (state === null) {
    commands.push({ kind: "hud", id: "logo", text: "NEON DRIFT", x: 640, y: 170, size: 170, color: "#4fe3ff", align: "center", fontId: "display" });
    commands.push({ kind: "hud", id: "sub", text: "ARROWS TO FLY  ·  HOLD SPACE TO FIRE", x: 640, y: 360, size: 30, color: "#d8c8ff", align: "center", fontId: "display" });
  }
  if (tick % 40 === 0) {
    const on = Math.floor(tick / 40) % 2 === 0;
    commands.push({ kind: "hud", id: "start", text: on ? "PRESS SPACE" : "", x: 640, y: 450, size: 40, color: "#ff4fd8", align: "center", fontId: "display" });
  }
  if (justPressed.includes("space")) commands.push({ kind: "sceneTransition", sceneId: "arena" });
  return { state: 1, commands };
}

({ tick, entity, state }) => {
  const s = state ?? { angle: 0 };
  s.angle += 0.012;
  const x = Math.cos(s.angle) * 6.4;
  const y = Math.sin(s.angle) * 3.3;
  return { state: s, commands: [{ kind: "setVelocity", x: (x - entity.x) * 60, y: (y - entity.y) * 60 }] };
}

