({ events, entity, world, state, random }) => {
  const s = state ?? { shake: 0 };
  for (const event of events) {
    if (event.kind !== "trigger") continue;
    if (event.event === "boom") s.shake = Math.max(s.shake, 0.18);
    if (event.event === "hurt") s.shake = Math.max(s.shake, 0.6);
    if (event.event === "bigboom") s.shake = Math.max(s.shake, 0.4);
  }
  const player = world.find((item) => item.source === "player");
  const base = s.base ?? { x: entity.x, y: entity.y };
  if (player) {
    base.x += (player.x - base.x) * 0.1;
    base.y += (player.y - base.y) * 0.1;
  }
  base.x = Math.max(-8, Math.min(8, base.x));
  base.y = Math.max(-4.5, Math.min(4.5, base.y));
  s.base = base;
  const x = base.x + (random() * 2 - 1) * s.shake;
  const y = base.y + (random() * 2 - 1) * s.shake;
  s.shake *= 0.86;
  if (s.shake < 0.01) s.shake = 0;
  return { state: s, commands: [{ kind: "setPosition", x, y }] };
}

({ tick, pressed, justPressed, events, entity, world, state, random }) => {
  const s = state ?? { vx: 0, vy: 0, angle: 0, cooldown: 0, lives: 3, invuln: 90, dead: 0, score: 0, combo: 1, comboTimer: 0, hud: "" };
  const commands = [];
  const hudText = (id, text, x, y, size, color, align) => commands.push({ kind: "hud", id, text, x, y, size, color, align, fontId: "display" });

  for (const event of events) {
    if (event.kind === "trigger" && event.event.startsWith("score:")) {
      s.score += Number(event.event.slice(6)) * s.combo;
      s.combo = Math.min(8, s.combo + 1);
      s.comboTimer = 120;
    }
  }
  if (s.comboTimer > 0 && --s.comboTimer === 0) s.combo = 1;

  if (s.dead > 0) {
    s.dead += 1;
    if (s.dead === 2) {
      hudText("over", "GAME OVER", 640, 250, 120, "#ff4fd8", "center");
      hudText("retry", "PRESS SPACE TO FLY AGAIN", 640, 400, 34, "#9fe8ff", "center");
    }
    if (s.dead > 60 && justPressed.includes("space")) commands.push({ kind: "sceneTransition", sceneId: "arena" });
    return { state: s, commands };
  }

  let hit = false;
  if (s.invuln > 0) s.invuln -= 1;
  else {
    for (const event of events) {
      if (event.kind !== "contact" || event.phase === "exit") continue;
      // A pair reports one contact per tick, so either side may name the player.
      const other = event.entityId === entity.id ? event.otherId : event.otherId === entity.id ? event.entityId : "";
      if (/^(mine|saw|brute)#/.test(other)) hit = true;
    }
  }

  const ax = (pressed.includes("right") ? 1 : 0) - (pressed.includes("left") ? 1 : 0);
  const ay = (pressed.includes("up") ? 1 : 0) - (pressed.includes("down") ? 1 : 0);
  const length = Math.hypot(ax, ay) || 1;
  s.vx = s.vx * 0.9 + (ax / length) * 1.25;
  s.vy = s.vy * 0.9 + (ay / length) * 1.25;
  const speed = Math.hypot(s.vx, s.vy);
  if (speed > 1.5) {
    const target = Math.atan2(s.vy, s.vx);
    let delta = target - s.angle;
    while (delta > Math.PI) delta -= Math.PI * 2;
    while (delta < -Math.PI) delta += Math.PI * 2;
    s.angle += delta * 0.25;
  }
  let x = entity.x;
  let y = entity.y;
  if (Math.abs(x) > 15.4) { x = Math.sign(x) * 15.4; s.vx = -s.vx * 0.4; commands.push({ kind: "setPosition", x, y }); }
  if (Math.abs(y) > 8.4) { y = Math.sign(y) * 8.4; s.vy = -s.vy * 0.4; commands.push({ kind: "setPosition", x, y }); }
  commands.push({ kind: "setVelocity", x: s.vx, y: s.vy });

  const blink = s.invuln > 0 && Math.floor(s.invuln / 4) % 2 === 0;
  commands.push({ kind: "setVisual", rotation: s.angle, opacity: blink ? 0.25 : 1 });

  if (speed > 2 && tick % 2 === 0) {
    const back = s.angle + Math.PI;
    commands.push({ kind: "spawn", prefabId: "thrust", x: x + Math.cos(back) * 0.45, y: y + Math.sin(back) * 0.45,
      velocityX: Math.cos(back) * 3 + (random() - 0.5) * 1.5, velocityY: Math.sin(back) * 3 + (random() - 0.5) * 1.5 });
  }

  if (s.cooldown > 0) s.cooldown -= 1;
  if (pressed.includes("space") && s.cooldown === 0) {
    let best = null;
    let bestDistance = 14;
    for (const item of world) {
      if (item.source !== "mine" && item.source !== "saw" && item.source !== "brute") continue;
      const distance = Math.hypot(item.x - x, item.y - y);
      if (distance < bestDistance) { best = item; bestDistance = distance; }
    }
    const aim = best ? Math.atan2(best.y - y, best.x - x) : s.angle;
    for (const offset of [-0.06, 0.06]) {
      const a = aim + offset;
      commands.push({ kind: "spawn", prefabId: "bolt", x: x + Math.cos(a) * 0.5, y: y + Math.sin(a) * 0.5,
        velocityX: Math.cos(a) * 24 + s.vx * 0.3, velocityY: Math.sin(a) * 24 + s.vy * 0.3 });
    }
    commands.push({ kind: "emit", event: "shoot" });
    s.cooldown = 6;
  }

  if (hit) {
    s.lives -= 1;
    s.invuln = 120;
    s.combo = 1;
    commands.push({ kind: "emit", event: "hurt" });
    commands.push({ kind: "spawn", prefabId: "shock", x, y });
    for (let i = 0; i < 8; i += 1) {
      const a = random() * Math.PI * 2;
      const v = 4 + random() * 8;
      commands.push({ kind: "spawn", prefabId: "sparkBlue", x, y, velocityX: Math.cos(a) * v, velocityY: Math.sin(a) * v });
    }
    if (s.lives <= 0) {
      s.dead = 1;
      commands.push({ kind: "setVisual", opacity: 0 });
      commands.push({ kind: "setVelocity", x: 0, y: 0 });
      commands.push({ kind: "emit", event: "bigboom" });
    }
  }

  const hud = `${s.score}|${s.combo}|${s.lives}`;
  if (hud !== s.hud) {
    s.hud = hud;
    hudText("score", String(s.score).padStart(7, "0"), 36, 18, 52, "#9fe8ff", "left");
    hudText("combo", s.combo > 1 ? `X${s.combo} COMBO` : "", 38, 76, 28, "#ffb13d", "left");
    // Bebas Neue has no triangle glyph, so the lives row uses the system font.
    commands.push({ kind: "hud", id: "lives", text: "▲ ".repeat(Math.max(0, s.lives)).trim(), x: 1244, y: 26, size: 30, color: "#4fe3ff", align: "right" });
  }
  return { state: s, commands };
}

({ events, world, state, random }) => {
  const s = state ?? { wave: 0, toSpawn: 0, timer: 90, pending: [], banner: 0 };
  const commands = [];
  const player = world.find((item) => item.source === "player");
  const alive = world.filter((item) => item.source === "mine" || item.source === "saw" || item.source === "brute").length;

  for (let i = s.pending.length - 1; i >= 0; i -= 1) {
    const item = s.pending[i];
    item.t -= 1;
    if (item.t <= 0) {
      commands.push({ kind: "spawn", prefabId: item.type, x: item.x, y: item.y });
      s.pending.splice(i, 1);
    }
  }
  if (s.toSpawn === 0 && s.pending.length === 0 && alive === 0) {
    if (s.timer === 90) {
      s.wave += 1;
      commands.push({ kind: "hud", id: "wave", text: `WAVE ${s.wave}`, x: 640, y: 270, size: 110, color: "#ffffff", align: "center", fontId: "display" });
      commands.push({ kind: "emit", event: "wave" });
      s.banner = 100;
    }
    s.timer -= 1;
    if (s.timer <= 0) {
      s.toSpawn = 5 + s.wave * 3;
      s.timer = 90;
    }
  }
  if (s.banner > 0 && --s.banner === 0) commands.push({ kind: "hud", id: "wave", text: "", x: 0, y: 0 });

  if (s.toSpawn > 0) {
    s.spawnClock = (s.spawnClock ?? 0) + 1;
    const interval = Math.max(10, 46 - s.wave * 4);
    if (s.spawnClock >= interval) {
      s.spawnClock = 0;
      let x = 0;
      let y = 0;
      for (let tries = 0; tries < 8; tries += 1) {
        x = (random() * 2 - 1) * 14.5;
        y = (random() * 2 - 1) * 7.5;
        if (!player || Math.hypot(x - player.x, y - player.y) > 6) break;
      }
      const roll = random();
      const bruteChance = Math.min(0.22, 0.06 * (s.wave - 1));
      const sawChance = Math.min(0.45, 0.12 * s.wave);
      const type = roll < bruteChance ? "brute" : roll < bruteChance + sawChance ? "saw" : "mine";
      commands.push({ kind: "spawn", prefabId: "warp", x, y });
      s.pending.push({ t: 40, x, y, type });
      s.toSpawn -= 1;
    }
  }
  return { state: s, commands };
}

({ tick, events, entity, world, state, random }) => {
  const s = state ?? { hp: 1, phase: random() * 100 };
  const commands = [];
  let killed = false;
  let touchedPlayer = false;
  for (const event of events) {
    if (event.kind !== "contact" || event.phase !== "enter") continue;
    // A pair reports one contact per tick, so either side may name this enemy.
    const other = event.entityId === entity.id ? event.otherId : event.otherId === entity.id ? event.entityId : "";
    if (other.startsWith("bolt#") && s.hp > 0) {
      s.hp -= 1;
      commands.push({ kind: "despawn", entityId: other });
      commands.push({ kind: "spawn", prefabId: "hitflash", x: entity.x, y: entity.y });
      commands.push({ kind: "spawn", prefabId: "spark", x: entity.x, y: entity.y,
        velocityX: (random() - 0.5) * 10, velocityY: (random() - 0.5) * 10 });
      if (s.hp <= 0) killed = true;
    }
    if (other === "player") touchedPlayer = true;
  }
  if (killed || touchedPlayer) {
    const x = entity.x;
    const y = entity.y;
    commands.push({ kind: "spawn", prefabId: "flash", x, y });
    commands.push({ kind: "spawn", prefabId: "shock", x, y });
    for (let i = 0; i < 10; i += 1) {
      const a = (i / 10) * Math.PI * 2 + random() * 0.5;
      const v = 5 + random() * 9;
      commands.push({ kind: "spawn", prefabId: "spark", x, y, velocityX: Math.cos(a) * v, velocityY: Math.sin(a) * v });
    }
    commands.push({ kind: "emit", event: 1 > 3 ? "bigboom" : "boom" });
    if (killed) commands.push({ kind: "emit", event: `score:${100}` });
    commands.push({ kind: "despawn", entityId: entity.id });
    return { state: s, commands };
  }
  const player = world.find((item) => item.source === "player");
  let vx = entity.velocityX;
  let vy = entity.velocityY;
  if (player) {
    const dx = player.x - entity.x;
    const dy = player.y - entity.y;
    const d = Math.hypot(dx, dy) || 1;
    let tx = (dx / d) * 3.2;
    let ty = (dy / d) * 3.2;
    const weave = Math.sin((tick + s.phase) * 0.08) * 0.8;
    tx += (-dy / d) * weave;
    ty += (dx / d) * weave;
    vx += (tx - vx) * 0.05;
    vy += (ty - vy) * 0.05;
  }
  commands.push({ kind: "setVelocity", x: vx, y: vy });
  return { state: s, commands };
}

